import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷五·22","description":"易小帖 - 卷五·22","frontmatter":{"title":"卷五·22","description":"易小帖 - 卷五·22"},"headers":[],"relativePath":"classics/yixiaotie/144.md","filePath":"classics/yixiaotie/144.md"}'),o={name:"classics/yixiaotie/144.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷五·22",tabindex:"-1"},[r("卷五·22 "),e("a",{class:"header-anchor",href:"#卷五·22","aria-label":"Permalink to “卷五·22”"},"​")],-1),e("p",null,"問：隋《梁四公記》，梁天監中，蜀闖四公謁武帝，帝命沉約作覆，令射。時太史適獲一鼠，緘匣以獻帝，筮之，遇蹇 之噬嗑 ，群臣占射無中者。惟帝謂：上坎下艮，坎為盜，而艮為石，則似有盜物不得而反見拘者，此必鼠也。噬嗑六爻無大咎，而終曰荷校滅耳，又似以噬齧獲戾，必死鼠也。而闖公之佔則曰：處暗而適，離舍艮止而之震動，是必幽隱之物，不當晝見，失本性而受拘繫者，其為鼠固也。然而又曰：坎雖為盜，而又為隱伏，盜能隱伏，猶未死也。惟從坎變離，離者南方之卦，日中則昃，日斂必死矣。且必有四鼠。金盛之月，金數四，此必四矣。及發，而止一生鼠。帝與闖公皆失色，逮晚，鼠死剖之，則懷妊三焉。此種璅屑，似兩晉已後，管輅郭璞諸筮法，不知與推易之法，春秋太史諸占筮同異若何。且蹇與噬嗑，正互順逆，並無兌象，而曰金盛，曰數四，某未解焉。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
